function norm(s){return String(s||"").toLowerCase().normalize("NFKD").replace(/[^a-z0-9]+/g," ").trim();}
function slug(s){return norm(s).replace(/\s+/g,"");}
function strip(h){return String(h||"").replace(/<script[\s\S]*?<\/script>/gi," ").replace(/<style[\s\S]*?<\/style>/gi," ").replace(/<[^>]+>/g," ").replace(/&amp;/g,"&").replace(/&quot;/g,'"').replace(/&#39;/g,"'").replace(/&lt;/g,"<").replace(/&gt;/g,">").replace(/\s+/g," ").trim();}
function json(data,status){return new Response(JSON.stringify(data),{status:status||200,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store","access-control-allow-origin":"*"}});}
async function fetchTimed(url,options={},ms=6000){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),ms);try{return await fetch(url,{...options,signal:controller.signal});}finally{clearTimeout(timer);}}
function directLinks(html, website, appName) {
 const out=[]; let base; try{base=new URL(website.includes("://")?website:"https://"+website);}catch{return out;}
 const brand=norm(appName).split(" ").filter(x=>x.length>2),rootLabel=root(base.hostname).split(".")[0].split(/[-_]/),trust=brand.some(x=>rootLabel.includes(x))?"high":"medium";
 const re=/<a\b[^>]*href=(['"])(.*?)\1[^>]*>([\s\S]*?)<\/a>/gi;let m;
 while((m=re.exec(html))&&out.length<100){try{const u=new URL(m[2],base),title=strip(m[3]);if(u.protocol!=="https:"||root(u.hostname)!==root(base.hostname))continue;const hay=(u.href+" "+title).toLowerCase();if(!/oauth|auth|developer|api|documentation|docs|permission|scope|verification|review|privacy|marketplace|\bapps?\b/.test(hay))continue;const score=(/oauth|auth/.test(hay)?5:0)+(/developer|api|docs|documentation/.test(hay)?4:0)+(/permission|scope|verification|review|privacy|marketplace/.test(hay)?3:0)+( /apps?/.test(hay)?2:0);out.push({url:u.href,title:title||u.pathname,snippet:"",confidence:trust,host:u.hostname,rank:score});}catch{}}
 out.sort((a,b)=>b.rank-a.rank);const home={url:base.origin,title:appName+" website supplied by requester",snippet:"",confidence:trust,host:base.hostname};
 return [home,...out].filter((x,i,a)=>a.findIndex(y=>y.url===x.url)===i).slice(0,12);
}
async function composioLookup(name){
 const key=slug(name), url=TOOLKITS+encodeURIComponent(key);
 const pages=await Promise.all([url,DIRECTORY].map(async target=>{try{const r=await fetchTimed(target,{headers:{"user-agent":"OAuthSetupAtlas/1.0"},cf:{cacheTtl:600,cacheEverything:true}},6000);return r.ok?strip(await r.text()).toLowerCase():"";}catch{return"";}}));
 const toolkitText=pages[0],directoryText=pages[1];
 if(toolkitText.includes("composio-managed oauth available"))return{status:"managed",toolkitSlug:key,url,evidence:"The current Composio toolkit page labels OAuth as managed."};
 if(toolkitText.includes("bring your own oauth app"))return{status:"bring_your_own",toolkitSlug:key,url,evidence:"The current Composio toolkit page says to bring your own OAuth app."};
 const a=directoryText.indexOf("composio-managed oauth available"),b=directoryText.indexOf("bring your own oauth app"),app=norm(name).replace(/\s+/g,"");if(a>=0&&directoryText.slice(a,b>a?b:undefined).includes(app))return{status:"managed",toolkitSlug:key,url:DIRECTORY,evidence:"The app appears in Composio's managed OAuth directory."};if(b>=0&&directoryText.slice(b).includes(app))return{status:"bring_your_own",toolkitSlug:key,url:DIRECTORY,evidence:"The app appears in Composio's bring-your-own OAuth list."};
 if(DIRECTORY_SNAPSHOT[norm(name)])return{status:DIRECTORY_SNAPSHOT[norm(name)],toolkitSlug:key,url:DIRECTORY,evidence:"Live page lookup was unavailable; using the official Composio directory listing verified for this demo on 2026-10-19.",sourceMode:"verified_snapshot",sourceCheckedAt:"2026-10-19"};
 return{status:"not_listed",toolkitSlug:key,url:DIRECTORY,evidence:"No matching toolkit found in Composio's public OAuth directory; the provider may still support OAuth."};
}
